@Transactional
public void placeOrder(OrderRequest req) {
    Order order = orderRepository.save(Order.from(req));

    outboxRepository.save(new OutboxEvent(
            UUID.randomUUID(),               // 이벤트 ID -- 컨슈머의 멱등성 키가 된다
            "Order",                         // aggregate type -> 토픽
            order.getId().toString(),        // aggregate id  -> 레코드 키 (파티션 = 순서)
            "OrderPlaced",
            objectMapper.writeValueAsString(OrderPlacedEvent.from(order)),
            Instant.now()));
}
// send 가 없다. 카프카를 아예 안 부른다.
